18	  # Bind helpers. In the Lua config every `bind` entry is `hl.bind(keys,
19	  # dispatcher, opts?)`, where keys join mods/keys with " + ".
20	  #
21	  # Two ways to render the dispatcher as a Lua expression via mkLuaInline:
22	  #   exec  - run a shell command. `hl.dsp.exec_cmd` is Hyprlang `exec`.
23	  #           (NB: `hl.dsp.exec_raw` is Hyprlang `execr` - run a *program*
24	  #           without a shell. Neither runs a dispatcher; dispatchers go
25	  #           through the structured `hl.dsp.*` API below.)
26	  #   dsp   - a structured dispatcher, e.g. hl.dsp.focus({ direction = "left" }),
27	  #           hl.dsp.window.close(), hl.dsp.window.move({ workspace = 1 }).
28	  # [=[ ... ]=] long brackets let shell commands keep their quotes and `]]`.
29	  exec = keys: cmd: {
30	    _args = [
31	      keys
32	      (mkLuaInline "hl.dsp.exec_cmd([=[${cmd}]=])")
33	    ];
34	  };
35	  execOpts = keys: cmd: opts: {
36	    _args = [
37	      keys
38	      (mkLuaInline "hl.dsp.exec_cmd([=[${cmd}]=])")
39	      opts
40	    ];
41	  };
42	  dsp = keys: luaExpr: {
43	    _args = [
44	      keys
45	      (mkLuaInline luaExpr)
46	    ];
47	  };
